<script setup>
import { ref, onMounted, inject } from "vue";
import { gsap } from "gsap";
import { Swiper, SwiperSlide } from "swiper/vue";
import { Navigation, EffectCards } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/effect-cards";

import {
  TV_ATTRACT_LINE_1,
  TV_ATTRACT_LINE_2,
  CHARACTERS,
} from "../game/config/GameConfig.js";

const props = defineProps({
  userData: {
    type: Object,
    default: () => ({ name: "Unknown", company: "" }),
  },
  selectedCharacterId: {
    type: Number,
    default: null,
  },
});

const emit = defineEmits(["start", "character-selected", "dev-start"]);

const swiperModules = [Navigation, EffectCards];

// Reorder characters so Kito (id: 1) is first. This completely avoids Swiper's initialSlide+loop bug
// because Swiper can start naturally at index 0 while still showing Kito as the default.
const orderedCharacters = [
  CHARACTERS.find((c) => c.id === 1), // Kito
  CHARACTERS.find((c) => c.id === 0), // Maya
  CHARACTERS.find((c) => c.id === 2), // Ankit
  CHARACTERS.find((c) => c.id === 3), // Rajat
].filter(Boolean);

const characters = ref(
  [...orderedCharacters, ...orderedCharacters].map((char, index) => ({
    id: char.id,
    uniqueKey: `${char.id}-${index}`, // Unique key for Vue v-for
    name: char.name,
    role: char.role,
    // The user prefers using 1-game.png for all characters over placeholder boxes
    image: "/img/1-game.png",
  })),
);

const onSwiperInit = (swiper) => {
  // Emit immediately on load so the 3D background matches the initial card!
  emit("character-selected", characters.value[0].id);
};

const onSlideChange = (swiper) => {
  const activeChar = characters.value[swiper.realIndex];
  if (activeChar) {
    emit("character-selected", activeChar.id);
  }
};

const musicState = inject("musicState");

// Dynamic leaderboard
const leaderboard = ref([]);

// Entrance-animation targets (Milestone 8). A GSAP timeline staggers these
// in on mount instead of everything just appearing at once; the leaderboard
// rows get their own separate stagger since they don't exist until the
// localStorage read above resolves.
const logoEl = ref(null);
const topStatsEl = ref(null);
const leftPanelEl = ref(null);
const rightPanelEl = ref(null);
const bottomBarEl = ref(null);
const leaderboardListEl = ref(null);

onMounted(() => {
  const stored = localStorage.getItem("chargeon_leaderboard");
  if (stored) {
    try {
      leaderboard.value = JSON.parse(stored);
    } catch (e) {}
  }

  // If empty, supply default mocks
  if (leaderboard.value.length === 0) {
    leaderboard.value = [
      { rank: 1, name: "--", score: "--" },
      { rank: 2, name: "--", score: "--" },
      { rank: 3, name: "--", score: "--" },
      { rank: 4, name: "--", score: "--" },
      { rank: 5, name: "--", score: "--" },
    ];
  } else {
    // Add rank property based on index
    leaderboard.value = leaderboard.value.map((entry, idx) => ({
      ...entry,
      rank: idx + 1,
    }));
  }

  const tl = gsap.timeline({ defaults: { ease: "power3.out" } });
  tl.from(logoEl.value, { opacity: 0, y: -16, scale: 0.85, duration: 0.5 })
    .from(topStatsEl.value, { opacity: 0, y: -12, duration: 0.4 }, "-=0.3")
    .from(leftPanelEl.value, { opacity: 0, x: -30, duration: 0.5 }, "-=0.2")
    .from(rightPanelEl.value, { opacity: 0, x: 30, duration: 0.5 }, "<")
    .from(bottomBarEl.value, { opacity: 0, y: 20, duration: 0.4 }, "-=0.2");

  if (leaderboardListEl.value) {
    gsap.from(leaderboardListEl.value.children, {
      opacity: 0,
      x: -15,
      duration: 0.35,
      stagger: 0.08,
      delay: 0.65,
      ease: "power2.out",
    });
  }
});
</script>

