    </header>

    <!-- Main Content -->
    <main class="dashboard-grid">
      <!-- Left Panel: Info & Leaderboard -->
      <section class="left-panel" ref="leftPanelEl">
        <div class="sf-native-badge">SALESFORCE NATIVE</div>
        <h1 class="panel-title">
          Charge<span class="highlight-o">O</span>n Power Run
        </h1>
        <p class="panel-desc">
          Outrun every payment problem. Unlock exciting goodies at every level,
          plus an exclusive <strong>ChargeOn Offer where you finish</strong>
        </p>

        <div class="leaderboard">
          <h4 class="text-dim">Top Performers</h4>
          <ul ref="leaderboardListEl">
            <li
              v-for="(entry, index) in leaderboard"
              :key="index"
              :class="{
                'rank-highlight': entry.name === props.userData.name,
              }"
            >
              <div class="rank-name-container">
                <span class="rank">{{ entry.rank }}.</span>
                <span class="name">{{ entry.name }}</span>
              </div>
              <span class="score">{{ entry.score }}</span>
            </li>
          </ul>
        </div>
      </section>

      <!-- Right Panel: Character Selector -->
      <section class="right-panel" ref="rightPanelEl">
        <h2 class="character-select-title">Select Your Character</h2>
        <div class="character-slider-container">
          <swiper
            :effect="'cards'"
            :cardsEffect="{
              rotate: true,
              slideShadows: false,
            }"
            :grabCursor="true"
            :speed="500"
            :loop="true"
            :navigation="true"
            :modules="swiperModules"
            class="character-swiper"
            @swiper="onSwiperInit"
            @slideChange="onSlideChange"
          >
            <swiper-slide v-for="char in characters" :key="char.uniqueKey">
              <div class="character-card" :class="'char-bg-' + char.id">
                <img :src="char.image" :alt="char.name" class="character-img" />
                <div class="character-info">
                  <h3 class="char-name">{{ char.name }}</h3>
                  <p class="char-role">{{ char.role }}</p>
                </div>
              </div>
            </swiper-slide>
          </swiper>
        </div>
      </section>
    </main>

    <!-- Bottom Actions -->
    <footer class="bottom-bar" ref="bottomBarEl">
      <div class="compliance-badges">
        <span>PCI-DSS Compliant | Agentexchange Listed</span>
      </div>

      <div class="action-buttons">
        <button class="btn-start-run" @click="emit('start')">
          <span>START RUN</span>
          <svg
            width="30"
            height="30"
            viewBox="0 0 39 35"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
